import json,math,re
import trajectory as t


def integer_text(value):
    return isinstance(value,str)and bool(re.fullmatch(r'0|-?[1-9][0-9]*',value))


def snapshot_items(snapshot,query):
    if (not isinstance(snapshot,dict)or set(snapshot)!={'query_id','input_sha256','epoch','candidates','items'}or
            snapshot['query_id']!=query['query_id']or snapshot['input_sha256']!=t.digest(query)or
