    candidates=snapshot['candidates'];seen=set();selected=[]
    for row in candidates:
        if not isinstance(row,dict)or set(row)!={'member','distance_m','stamp','age_s','reason'}or not isinstance(row['member'],str)or row['member']in seen:raise ValueError('candidate identity')
        seen.add(row['member'])
        if type(row['distance_m'])not in(int,float)or not math.isfinite(row['distance_m'])or not 0<=row['distance_m']<=query['radius_m']+.0001:raise ValueError('candidate distance')
        stamp=row['stamp']
