def keys(prefix):
    if not isinstance(prefix,str)or not re.fullmatch(r'of:[a-f0-9]{16,48}:',prefix):raise ValueError('dedicated prefix')
    return[prefix+name for name in('geo','times','meta','batches','events','batch_events','queries')]


