def record(raw):
    if not isinstance(raw,str):raise ValueError('native receipt missing')
    value=json.loads(raw)
    if not isinstance(value,dict):raise ValueError('native receipt object required')
    for field in('candidates','items'):
        if field in value and not isinstance(value[field],list):raise ValueError('native JSON array required')
    return value


def native_preflight(command,prefix,manifest):
    managed=keys(prefix)
    for index,key in enumerate(managed):
        if command('TYPE',key)not in('none','zset'if index==0 else'hash'):raise ValueError('managed key type')
    flat_times=command('HGETALL',managed[1]);all_times=dict(zip(flat_times[::2],flat_times[1::2]))
    for raw in all_times.values():
        if not isinstance(raw,str)or not re.fullmatch(r'0|[1-9][0-9]*',raw)or int(raw)>2**53-1:raise ValueError('invalid existing timestamp')
    old=command('HGET',managed[3],manifest['batch_id'])
    epoch=command('HGET',managed[2],'epoch')
    if epoch is not None and(not re.fullmatch(r'0|[1-9][0-9]*',epoch)or int(epoch)>1000000000):raise ValueError('epoch budget')
    if old is not None:
        if record(old)['digest']!=digest(manifest):raise ValueError('batch digest conflict')
    else:
