        if pending not in(None,''):raise ValueError('another batch pending')
    new_members=set();versions={};additional=0
    for event in manifest['events']:
        known=command('HGET',managed[4],event['event_id'])
        if known is not None and record(known)['input_sha256']!=digest(event):raise ValueError('event identity conflict')
        raw=command('HGET',managed[1],event['member'])
        if raw is not None and(not re.fullmatch(r'0|[1-9][0-9]*',raw)or int(raw)>2**53-1):raise ValueError('invalid existing timestamp')
        if event['member']not in versions:versions[event['member']]=None if raw is None else int(raw)
        if known is None and(versions[event['member']]is None or versions[event['member']]<event['stamp']):
            additional+=1;versions[event['member']]=event['stamp']
        if command('ZSCORE',managed[0],event['member'])is None:new_members.add(event['member'])
    if command('ZCARD',managed[0])+len(new_members)>10000:raise ValueError('candidate budget exceeded')
    if int(epoch or 0)+additional>1000000000:raise ValueError('epoch budget')
    return managed


ARTIFACTS=('input.json','events.jsonl','queries.jsonl','manifest.json','audit.json')+tuple(name+'-%03d.json'%i for name in('candidates','result')for i in range(8))


def directory_for(root,batch_id):
    root=Path(root).resolve();root.mkdir(parents=True,exist_ok=True);directory=root/batch_id
