    return {'schema':1,'batch_id':manifest['batch_id'],'batch_sha256':digest(manifest),'events':len(event_rows),'queries':len(query_rows),
            'accepted_new':sum(r['record']['event']['accepted']and not r['record']['reused']for r in event_rows),
            'rejected_new':sum(not r['record']['event']['accepted']and not r['record']['reused']for r in event_rows),
            'replayed':sum(r['record']['reused']for r in event_rows),
