import json,math,re
import trajectory as t


def integer_text(value):
    return isinstance(value,str)and bool(re.fullmatch(r'0|-?[1-9][0-9]*',value))


def snapshot_items(snapshot,query):
    if (not isinstance(snapshot,dict)or set(snapshot)!={'query_id','input_sha256','epoch','candidates','items'}or
            snapshot['query_id']!=query['query_id']or snapshot['input_sha256']!=t.digest(query)or
            type(snapshot['epoch'])is not int or snapshot['epoch']<0 or not isinstance(snapshot['candidates'],list)or len(snapshot['candidates'])>10000):raise ValueError('snapshot identity')
    candidates=snapshot['candidates'];seen=set();selected=[]
    for row in candidates:
        if not isinstance(row,dict)or set(row)!={'member','distance_m','stamp','age_s','reason'}or not isinstance(row['member'],str)or row['member']in seen:raise ValueError('candidate identity')
        seen.add(row['member'])
        if type(row['distance_m'])not in(int,float)or not math.isfinite(row['distance_m'])or not 0<=row['distance_m']<=query['radius_m']+.0001:raise ValueError('candidate distance')
        stamp=row['stamp']
        if stamp is None:
            reason='missing'
            if row['age_s']is not None:raise ValueError('missing timestamp age')
        else:
            if not integer_text(stamp)or not 0<=int(stamp)<=2**53-1:raise ValueError('candidate timestamp')
            age=query['now']-int(stamp)
            if not integer_text(row['age_s'])or int(row['age_s'])!=age:raise ValueError('candidate age')
            reason='future'if age<0 else'stale'if age>query['max_age']else'eligible'
        if row['reason']!=reason:raise ValueError('candidate reason')
        if reason=='eligible':selected.append({'member':row['member'],'distance_m':row['distance_m'],'age_s':int(row['age_s'])})
    ordered=sorted(candidates,key=lambda row:(row['distance_m'],row['member'].encode()))
    if candidates!=ordered:raise ValueError('candidate ordering')
    selected=selected[:query['limit']]
    if not isinstance(snapshot['items'],list):raise ValueError('selected item array')
    for row in snapshot['items']:
        if (not isinstance(row,dict)or set(row)!={'member','distance_m','age_s'}or not isinstance(row['member'],str)or
                type(row['distance_m'])not in(int,float)or not math.isfinite(row['distance_m'])or type(row['age_s'])is not int):raise ValueError('selected item schema')
    if snapshot['items']!=selected:raise ValueError('snapshot selection')
    return selected


def audit(command,prefix,manifest,root):
    t.validate(manifest);managed=t.keys(prefix);directory=t.directory_for(root,manifest['batch_id'])
    saved_input=json.loads((directory/'input.json').read_text(encoding='utf-8'))
    if t.validate(saved_input)!=t.digest(manifest):raise ValueError('input changed')
    events=t.load_prefix(directory/'events.jsonl',manifest,'events',command,managed)
    queries=t.load_prefix(directory/'queries.jsonl',manifest,'queries',command,managed)
    if len(events)!=len(manifest['events'])or len(queries)!=len(manifest['queries']):raise ValueError('incomplete evidence')
    state=t.complete_state(command,managed,manifest)
    for entry,row in zip(manifest['events'],events):
        original=row['record']
        if not isinstance(original,dict)or set(original)!={'event','reused'}or type(original['reused'])is not bool:raise ValueError('event outcome')
        event=original['event']
        if (not isinstance(event,dict)or set(event)!={'event_id','input_sha256','member','stamp','previous_stamp','accepted','epoch'}or
                event['event_id']!=entry['event_id']or event['input_sha256']!=t.digest(entry)or event['member']!=entry['member']or event['stamp']!=str(entry['stamp'])or type(event['accepted'])is not bool or type(event['epoch'])is not int or not 0<=event['epoch']<=state['epoch']):raise ValueError('event receipt identity')
        previous=event['previous_stamp']
        if previous is not None and(not integer_text(previous)or not 0<=int(previous)<=2**53-1):raise ValueError('previous timestamp')
        if event['accepted']is not(previous is None or int(previous)<entry['stamp']):raise ValueError('event version outcome')
        if t.record(command('HGET',managed[4],entry['event_id']))!=event:raise ValueError('global event ledger differs')
    for index,(query,row)in enumerate(zip(manifest['queries'],queries)):
        snapshot=row['record'];items=snapshot_items(snapshot,query)
        if snapshot['epoch']!=state['epoch']:raise ValueError('mixed graph epoch')
        candidate_product={'query_id':snapshot['query_id'],'epoch':snapshot['epoch'],'candidates':snapshot['candidates']}
        result_product={'query_id':snapshot['query_id'],'epoch':snapshot['epoch'],'partial':False,'items':items}
        if json.loads((directory/('candidates-%03d.json'%index)).read_text(encoding='utf-8'))!=candidate_product:raise ValueError('candidate artifact differs')
        if json.loads((directory/('result-%03d.json'%index)).read_text(encoding='utf-8'))!=result_product:raise ValueError('result artifact differs')
    expected=t.products(manifest,events,queries)
    actual=json.loads((directory/'manifest.json').read_text(encoding='utf-8'))
    if not isinstance(actual,dict)or any(type(actual.get(field))is not int for field in('schema','events','queries','accepted_new','rejected_new','replayed')):raise ValueError('manifest counter schema')
    if actual!=expected:raise ValueError('manifest differs')
    result={'schema':1,'batch_id':manifest['batch_id'],'batch_sha256':t.digest(manifest),'verified':True,'manifest_sha256':t.digest(expected),'accepted_new':expected['accepted_new'],'rejected_new':expected['rejected_new'],'replayed':expected['replayed']}
    t.publish(directory/'audit.json',result)
    return result

