import threading
def isolated_probe(open_connection,key,wait_blocked,cancel=False):
    blocking=normal=None;thread=None;state={}
    try:
        blocking=open_connection('blocking');normal=open_connection('normal');client_id=blocking.command('CLIENT','ID')
        def consume():
            try:state['result']=blocking.command('BLPOP',key,1)
            except Exception as e:state['error']=e
        thread=threading.Thread(target=consume);thread.start()
        wait_blocked(client_id)
        pong=normal.command('PING')
        wait_blocked(client_id)
        if cancel:
            if normal.command('CLIENT','UNBLOCK',client_id,'TIMEOUT')!=1:raise RuntimeError('consumer was not blocked')
        thread.join(3)
        if thread.is_alive():raise RuntimeError('consumer did not finish')
        if 'error' in state:raise state['error']
        if state.get('result') is not None:raise RuntimeError('unexpected message consumed')
        return {'ping':pong,'blocked_result':state['result'],'reused_ping':blocking.command('PING')}
    finally:
        if thread is not None and thread.is_alive():thread.join(3)
        if normal is not None:normal.close()
        if blocking is not None:blocking.close()
